  "pack.schema.yaml": "# Schema for jurisdiction pack metadata (pack.yaml) — REQ-PACK-2.\n# The schema is the reviewer: a structurally valid pack with passing\n# snapshots is mergeable on translation review alone.\n# A JSON mirror is generated at packages/packs/schema/pack.schema.json.\ntype: object\nrequired: [schemaVersion, country, name, languages, defaultLanguage, legal, enforcement, quality]\nadditionalProperties: false\nproperties:\n  schemaVersion:\n    type: integer\n    enum: [1]\n  country:\n    type: string\n    pattern: \"^[a-z]{2}$\"\n  name:\n    type: string\n    minLength: 1\n  languages:\n    type: array\n    minItems: 1\n    items:\n      type: string\n      pattern: \"^[a-z]{2}(-[A-Za-z0-9-]+)?$\"\n  defaultLanguage:\n    type: string\n    pattern: \"^[a-z]{2}(-[A-Za-z0-9-]+)?$\"\n  legal:\n    type: object\n    required: [act, sources]\n    properties:\n      act:\n        type: string\n        minLength: 1\n      references:\n        type: array\n        items:\n          type: string\n      sources:\n        type: array\n        minItems: 1\n        items:\n          type: string\n          pattern: \"^https://\"\n  enforcement:\n    type: object\n    required: [name]\n    properties:\n      name:\n        type: string\n        minLength: 1\n      url:\n        type: string\n      email:\n        type: string\n      phone:\n        type: string\n      address:\n        type: string\n      verified:\n        type: string\n        format: date\n      conciliation:\n        # Some member states give consumers a conciliation or ombudsman\n        # route before, or instead of, the market surveillance authority\n        # (Germany's Schlichtungsstelle BGG under § 34 BFSG, for example).\n        # Naming only the surveillance authority would send people to the\n        # wrong door, so packs may carry both.\n        type: object\n        required: [name]\n        properties:\n          name:\n            type: string\n            minLength: 1\n          url:\n            type: string\n          email:\n            type: string\n          phone:\n            type: string\n          address:\n            type: string\n          note:\n            type: string\n  deadlines:\n    type: object\n    properties:\n      enforceableSince:\n        type: string\n        format: date\n      notes:\n        type: string\n  quality:\n    type: string\n    enum: [bronze, silver, gold]\n  maintainers:\n    type: array\n    items:\n      type: string\n  notes:\n    type: string\n",
